// HasDiscoveryConfig applies the HasEdge predicate on the "discovery_config" edge.
func HasDiscoveryConfig() predicate.DiscoveryExecutionHistory {
	return predicate.DiscoveryExecutionHistory(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, DiscoveryConfigTable, DiscoveryConfigColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasDiscoveryConfigWith applies the HasEdge predicate on the "discovery_config" edge with a given conditions (other predicates).
func HasDiscoveryConfigWith(preds ...predicate.CiTypeDiscoveryConfig) predicate.DiscoveryExecutionHistory {
	return predicate.DiscoveryExecutionHistory(func(s *sql.Selector) {
		step := newDiscoveryConfigStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

